def transform(grid):
    h, w = len(grid), len(grid[0])

    stripes = [(r, row[0]) for r, row in enumerate(grid)
               if row[0] != 0 and all(v == row[0] for v in row)]

    if stripes:
        # The horizontal markers specify a repeating row-color cycle.
        # Find the shortest cycle consistent with all marker positions.
        for period in range(1, h + 1):
            vals = {}
            consistent = True
            for r, color in stripes:
                k = r % period
                if k in vals and vals[k] != color:
                    consistent = False
                    break
                vals[k] = color
            if consistent:
                break
        # Fill unspecified positions by carrying the nearest preceding
        # known cycle color around the cycle.
        for k in range(period):
            if k not in vals:
                prev = next((j for d in range(1, period + 1)
                             for j in [(k - d) % period] if j in vals), None)
                vals[k] = vals[prev] if prev is not None else 0
        return [[vals[r % period]] * w for r in range(h)]

    # For diagonal-band inputs, read the repeating diagonal motif and tile it.
    nonzero = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != 0]
    if nonzero:
        for period in range(1, min(h, w) + 1):
            buckets = [[] for _ in range(period)]
            for r, c, color in nonzero:
                buckets[(r + c) % period].append(color)
            if all(buckets):
                motif = []
                for b in buckets:
                    motif.append(max(set(b), key=b.count))
                # Prefer a motif consistent with all observed diagonal cells.
                if all(motif[(r + c) % period] == color
                       for r, c, color in nonzero):
                    return [[motif[(r + c) % period] for c in range(w)]
                            for r in range(h)]
    return [row[:] for row in grid]
